import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface ChartVisualizationProps {
  data: any[];
  type: string;
  title?: string;
}

export function ChartVisualization({ data, type, title = "Визуализация Данных" }: ChartVisualizationProps) {
  if (!data || data.length === 0) {
    return (
      <Card>
        <CardContent className="pt-6">
          <div className="h-64 bg-muted/30 rounded-lg flex items-center justify-center">
            <div className="text-center text-muted-foreground">
              <i className="fas fa-chart-line text-3xl mb-2"></i>
              <p className="text-sm">Нет данных для визуализации</p>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  // Prepare data for charts
  const chartData = data.map((item, index) => ({
    name: item[Object.keys(item)[0]] || `Item ${index + 1}`,
    value: parseFloat(item[Object.keys(item)[1]]) || 0,
    ...item
  }));

  const renderChart = () => {
    switch (type.toLowerCase()) {
      case 'bar':
      case 'column':
        return (
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip />
              <Bar dataKey="value" fill="hsl(var(--primary))" />
            </BarChart>
          </ResponsiveContainer>
        );

      case 'line':
      default:
        return (
          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip />
              <Line 
                type="monotone" 
                dataKey="value" 
                stroke="hsl(var(--primary))" 
                strokeWidth={2}
                dot={{ fill: "hsl(var(--primary))" }}
              />
            </LineChart>
          </ResponsiveContainer>
        );
    }
  };

  return (
    <Card className="bg-card border border-border" data-testid="chart-visualization">
      <CardHeader>
        <CardTitle className="text-sm font-medium flex items-center">
          <i className="fas fa-chart-line mr-2"></i>
          {title}
        </CardTitle>
      </CardHeader>
      <CardContent>
        {renderChart()}
        <p className="text-xs text-muted-foreground mt-2 text-center">
          Интерактивный график • Созданный агентом Visualizer
        </p>
      </CardContent>
    </Card>
  );
}

client/src/components/data/data-table.ts.content:
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

interface DataTableProps {
  data: any[];
  title?: string;
}

export function DataTable({ data, title = "Результаты Запроса" }: DataTableProps) {
  if (!data || data.length === 0) {
    return (
      <Card>
        <CardContent className="pt-6">
          <p className="text-muted-foreground text-center">Нет данных для отображения</p>
        </CardContent>
      </Card>
    );
  }

  const columns = Object.keys(data[0]);

  const formatCellValue = (value: any) => {
    if (value === null || value === undefined) return '-';
    if (typeof value === 'number') {
      // Format numbers with appropriate decimal places
      return new Intl.NumberFormat('ru-RU').format(value);
    }
    if (typeof value === 'string' && value.match(/^\d{4}-\d{2}-\d{2}/)) {
      // Format dates
      return new Date(value).toLocaleDateString('ru-RU');
    }
    return String(value);
  };

  return (
    <Card className="bg-card border border-border" data-testid="data-table">
      <CardHeader className="px-4 py-2 bg-muted border-b border-border">
        <CardTitle className="text-sm font-medium">{title}</CardTitle>
      </CardHeader>
      <CardContent className="p-0">
        <div className="overflow-x-auto">
          <Table>
            <TableHeader>
              <TableRow className="bg-muted/50">
                {columns.map((column) => (
                  <TableHead 
                    key={column} 
                    className="px-4 py-2 text-left font-medium text-xs"
                    data-testid={`table-header-${column}`}
                  >
                    {column}
                  </TableHead>
                ))}
              </TableRow>
            </TableHeader>
            <TableBody>
              {data.map((row, index) => (
                <TableRow 
                  key={index} 
                  className="border-t border-border"
                  data-testid={`table-row-${index}`}
                >
                  {columns.map((column) => (
                    <TableCell 
                      key={column} 
                      className="px-4 py-2 text-sm"
                      data-testid={`table-cell-${index}-${column}`}
                    >
                      {formatCellValue(row[column])}
                    </TableCell>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      </CardContent>
    </Card>
  );
}

